cat > Program.cs << 'EOF'
using System.Diagnostics;
using System.Runtime.CompilerServices;
using TextAnalysis;

const int WarmupIterations = 100;
const int BenchIterations = 10000;

var sampleText = GenerateSampleText();
var analyzer = new TextAnalyzer(sampleText);

Console.WriteLine($"Runtime: {System.Runtime.InteropServices.RuntimeInformation.FrameworkDescription}");
Console.WriteLine($"Iterations: {BenchIterations}");
Console.WriteLine($"Words in sample: {analyzer.WordCount}");
Console.WriteLine();

// Warmup
for (int i = 0; i < WarmupIterations; i++)
{
    _ = analyzer.AverageWordLength();
    _ = analyzer.WordLengthHistogram();
    _ = analyzer.UniqueWordCount();
}

// Benchmark AverageWordLength
var elapsed = Measure(() => analyzer.AverageWordLength(), BenchIterations);
Console.WriteLine($"AverageWordLength:   {elapsed.TotalNanoseconds / BenchIterations,10:F1} ns/op");

// Benchmark WordLengthHistogram
elapsed = Measure(() => analyzer.WordLengthHistogram(), BenchIterations);
Console.WriteLine($"WordLengthHistogram: {elapsed.TotalNanoseconds / BenchIterations,10:F1} ns/op");

// Benchmark UniqueWordCount
elapsed = Measure(() => analyzer.UniqueWordCount(), BenchIterations);
Console.WriteLine($"UniqueWordCount:     {elapsed.TotalNanoseconds / BenchIterations,10:F1} ns/op");

static TimeSpan Measure(Action action, int iterations)
{
    // Force GC before measurement
    GC.Collect();
    GC.WaitForPendingFinalizers();
    GC.Collect();

    var sw = Stopwatch.StartNew();
    for (int i = 0; i < iterations; i++)
        action();
    sw.Stop();
    return sw.Elapsed;
}

static string GenerateSampleText()
{
    var words = new string[1000];
    for (int i = 0; i < 1000; i++)
    {
        words[i] = (i % 7) switch
        {
            0 => "hello",
            1 => "world",
            2 => "benchmarking",
            3 => "is",
            4 => "quite",
            5 => "interesting",
            _ => "indeed"
        };
    }
    return string.Join(" ", words);
}
